(7191742, 1106339, 42100, '<td valign="top">The fascinating textures and patterns make this my top pick of this challenge.  Perfect desaturation and a well thought out composition really keep this photo from becoming a disaster with the sea of chaos happening in this scene.  Skillfully executed!</td>', 'The fascinating textures and patterns make this my top pick of this challenge.  Perfect desaturation and a well thought out composition really keep this photo from becoming a disaster with the sea of chaos happening in this scene.  Skillfully executed!', '2014-03-19 13:33:52.000000', NULL, 1),
(7191745, 1106192, 42100, '<td valign="top">The moody atmosphere here makes this a very close second, to my top pick of this challenge.  You used every element of this scene, from the crossing, to the rails and structures, to pull the viewer into and through this photograph.  Nicely done!</td>', 'The moody atmosphere here makes this a very close second, to my top pick of this challenge.  You used every element of this scene, from the crossing, to the rails and structures, to pull the viewer into and through this photograph.  Nicely done!', '2014-03-19 13:42:01.000000', NULL, 1),
(7191747, 1106319, 42100, '<td valign="top">I''m a bit torn on this image...I detest photographs with strong white backgrounds.  But, I find the rest of this well executed, and the sign with it''s age and distress is rather interesting.  I''m also smart enough(or at least I like think I am) to realize that a bad background could very easily kill this photo!</td>', 'I''m a bit torn on this image...I detest photographs with strong white backgrounds.  But, I find the rest of this well executed, and the sign with it''s age and distress is rather interesting.  I''m also smart enough(or at least I like think I am) to realize that a bad background could very easily kill this photo!', '2014-03-19 13:56:49.000000', NULL, 1),
(7191755, 1105956, 129147, '<td valign="top">I like the composition here, wish for a darker background as the white object in the center pulls my eye away from the trucks.</td>', 'I like the composition here, wish for a darker background as the white object in the center pulls my eye away from the trucks.', '2014-03-19 14:23:00.000000', NULL, 1),
