(7192710, 1106089, 150277, '<td valign="top">On second glance, this is a favorite.  Reminds me of the sadness of the homeless who wander.</td>', 'On second glance, this is a favorite.  Reminds me of the sadness of the homeless who wander.', '2014-03-22 12:47:47.000000', NULL, 1),
(7192982, 1106203, 147579, '<td valign="top">Beautiful colour contrasts.  If it wern''t for the two story station I would swear it was my home town.  Jumps right out at you.</td>', 'Beautiful colour contrasts.  If it wern''t for the two story station I would swear it was my home town.  Jumps right out at you.', '2014-03-23 15:45:11.000000', NULL, 1),
(7192983, 1106395, 147579, '<td valign="top">This is poignant to me, we just lost our passenger train. Good bright definition.</td>', 'This is poignant to me, we just lost our passenger train. Good bright definition.', '2014-03-23 15:50:14.000000', NULL, 1),
(7192984, 1106296, 147579, '<td valign="top">Great idea, but too busy.</td>', 'Great idea, but too busy.', '2014-03-23 15:51:09.000000', NULL, 1),
(7192986, 1106246, 147579, '<td valign="top">Love the definition on this one.  Tie and track placement just draw you right in.</td>', 'Love the definition on this one.  Tie and track placement just draw you right in.', '2014-03-23 15:53:16.000000', NULL, 1),
(7192987, 1106328, 147579, '<td valign="top">Liking the misty edging with the sharp mid point.</td>', 'Liking the misty edging with the sharp mid point.', '2014-03-23 15:54:57.000000', NULL, 1),
(7192988, 1106405, 147579, '<td valign="top">beautiful use of subtle colours, faded at foreground, brighter at back.</td>', 'beautiful use of subtle colours, faded at foreground, brighter at back.', '2014-03-23 15:58:53.000000', NULL, 1),
(7192990, 1106299, 147579, '<td valign="top">Normally, I would think pics of overhead wire unpristine, but this pic is all about wire, from the tracks to the overhead.  Very clear.</td>', 'Normally, I would think pics of overhead wire unpristine, but this pic is all about wire, from the tracks to the overhead.  Very clear.', '2014-03-23 16:01:53.000000', NULL, 1),
(7192991, 1105830, 147579, '<td valign="top">Good definition.  Which track should I take? Really makes me want to find out.</td>', 'Good definition.  Which track should I take? Really makes me want to find out.', '2014-03-23 16:03:17.000000', NULL, 1),
(7192992, 1106177, 147579, '<td valign="top">Excellent colour, Very painting like.</td>', 'Excellent colour, Very painting like.', '2014-03-23 16:05:20.000000', NULL, 1),
(7192993, 1105957, 147579, '<td valign="top">Some pictures just have that beckoning feeling.</td>', 'Some pictures just have that beckoning feeling.', '2014-03-23 16:06:55.000000', NULL, 1),
