INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7193817, 1106403, 129147, '<td valign="top">Don''t care for the cardboard, it pulls my eye to it each time I''ve looked at this photo.</td>', 'Don''t care for the cardboard, it pulls my eye to it each time I''ve looked at this photo.', '2014-03-25 13:03:01.000000', NULL, 1),
(7193818, 1105928, 129147, '<td valign="top">Not sure that I understand the processing here. That''s a lot of yellow.</td>', 'Not sure that I understand the processing here. That''s a lot of yellow.', '2014-03-25 13:03:54.000000', NULL, 1),
(7193826, 1106144, 129147, '<td valign="top">Wish that there were more room in the front of the image. The stake at the fron of the engine doesn''t help either.</td>', 'Wish that there were more room in the front of the image. The stake at the fron of the engine doesn''t help either.', '2014-03-25 13:31:07.000000', NULL, 1),
(7193870, 1106299, 173844, '<td valign="top">A veritable symphony of rail lines overlaid with a scratchy counterpoint of towers and wires.  And then there''s the staccato of the signal lights, to extend the metaphor.  All this busy detail is wonderfully captured at a perfect time of day.  I find it moving.</td>', 'A veritable symphony of rail lines overlaid with a scratchy counterpoint of towers and wires.  And then there''s the staccato of the signal lights, to extend the metaphor.  All this busy detail is wonderfully captured at a perfect time of day.  I find it moving.', '2014-03-25 15:51:06.000000', NULL, 1),
(7193871, 1106047, 173844, '<td valign="top">The extreme busyness of this image is what fascinates and draws me to it.  Yet the train cars shown are idle, so the effect is a compounding of lines, masses and just plain stuff.  It''s all setting, no action.  It''s a complicated and choppy abstract that you can peer into.  Of course there''s a little slice of track that''s in focus as a reference point.  The background blur of poles, trees and whatnot functions as a sort of bokeh.  My favorite in the challenge.<br/>It can be dizzying, but that''s the price of admission.</td>', 'The extreme busyness of this image is what fascinates and draws me to it.  Yet the train cars shown are idle, so the effect is a compounding of lines, masses and just plain stuff.  It''s all setting, no action.  It''s a complicated and choppy abstract that you can peer into.  Of course there''s a little slice of track that''s in focus as a reference point.  The background blur of poles, trees and whatnot functions as a sort of bokeh.  My favorite in the challenge.It can be dizzying, but that''s the price of admission.', '2014-03-25 15:52:40.000000', NULL, 1),
(7193872, 1106119, 173844, '<td valign="top">A charming study of some sort of railroad vehicle and its companion patch of vegetation.  It''s both gritty and delicate which, I think, gives it its appeal. The sepia tone is very becoming.  The blurred background, featuring a tree in silhouette, is also very attractive.</td>', 'A charming study of some sort of railroad vehicle and its companion patch of vegetation.  It''s both gritty and delicate which, I think, gives it its appeal. The sepia tone is very becoming.  The blurred background, featuring a tree in silhouette, is also very attractive.', '2014-03-25 15:56:38.000000', NULL, 1),
(7193873, 1106218, 173844, '<td valign="top">The extreme detail and black and white presentation force a description, for me, of Gritty.  And there, as the title states, we have it.  It''s a quite successful image that is also strong on shape and contrast, to say nothing of the intrinsic interest of the railroad chassis (I guess) components.</td>', 'The extreme detail and black and white presentation force a description, for me, of Gritty.  And there, as the title states, we have it.  It''s a quite successful image that is also strong on shape and contrast, to say nothing of the intrinsic interest of the railroad chassis (I guess) components.', '2014-03-25 15:57:53.000000', NULL, 1),
(7193874, 1106297, 173844, '<td valign="top">There''s a wonderful and modern abstract feel to this.</td>', 'There''s a wonderful and modern abstract feel to this.', '2014-03-25 15:58:11.000000', NULL, 1),
